import re

def closest_integer(num_str):
    if not re.match(r'^-?\d+(\.\d+)?$', num_str):
        raise ValueError("Input is not a valid number format")

    num = float(num_str)
    rounded_num = round(num)

    if rounded_num > num:
        return int(rounded_num)
    elif rounded_num < num:
        return int(rounded_num + 1)
    else:
        if num >= 0:
            return int(rounded_num)
        else:
            return int(rounded_num - 1)

