import re

def closest_integer(num_str):
    if not re.match(r'^-?\d+(\.\d+)?$', num_str):
        raise ValueError("Input is not a valid number format")

    num = float(num_str)
    dist_to_lower = num - int(num)
    dist_to_higher = 1 - dist_to_lower

    if dist_to_lower < dist_to_higher:
        return int(num)
    elif dist_to_lower > dist_to_higher:
        return int(num) + 1
    else:
        if num >= 0:
            return int(num) + 1
        else:
            return int(num) - 1

