def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    if is_palindromic(arr):
        return 0

    middle = len(arr) // 2
    left_changes = count_changes(arr[:middle])
    right_changes = count_changes(arr[middle + len(arr) % 2:])

    return min(left_changes, right_changes)
